def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count statistics
    opp_c = 0
    my_d = 0
    cc = cd = dc = dd = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'D':
            my_d += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1

    opp_d = n - opp_c
    my_last, opp_last = history[-1]

    # Opening: cooperate to establish mutual cooperation.
    if n < 4:
        return 'C'

    # Detect long opponent cooperation streak.
    coop_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        coop_streak += 1
        i -= 1

    # Detect long opponent defection streak.
    def_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        def_streak += 1
        i -= 1

    # Endgame exploitation: if opponent is a cooperator, defect near end.
    if n >= 92:
        if opp_d * 4 <= n:  # mostly cooperative
            return 'D'
        if def_streak >= 2:
            return 'D'
        if coop_streak >= 3:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Heavy defection regime: punish firmly.
    if def_streak >= 3:
        return 'D'

    recent = history[-8:] if n >= 8 else history
    rn = len(recent)
    r_opp_d = sum(1 for m, o in recent if o == 'D')
    r_my_d = sum(1 for m, o in recent if m == 'D')

    # Aggressive opponent: mostly defect but occasionally probe cooperation.
    if r_opp_d * 2 > rn:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Strongly cooperative opponent: mostly cooperate, rare probe.
    if opp_d == 0 or (n >= 10 and opp_d * 10 <= n):
        if n >= 85:
            return 'D'
        if rng.random() < 0.03:
            return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness to recover cooperation.
    if opp_last == 'D':
        if def_streak >= 2:
            return 'D'
        if my_last == 'D':
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # I cooperated, opponent defected: retaliate but sometimes forgive.
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated.
    if my_last == 'D':
        # Return to cooperation unless exploiter-like.
        if r_opp_d * 2 >= rn:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'C'

    if coop_streak >= 4:
        # Long cooperation: occasionally test if safe.
        if n < 85 and my_d * 3 < n and rng.random() < 0.05:
            return 'D'
        return 'C'

    return 'C'
